// Checks the built site in dist/ (run `npm run build` first).
// No dependency: only Node built-ins. The HTML is generated by Astro, so it is regular
// enough to be read with simple patterns.
import { readdirSync, readFileSync, existsSync, statSync } from "node:fs";
import { join, relative, sep } from "node:path";

const DIST = "dist";
const LANGS = ["fr", "en"];
const SITE = "https://amandinecousin.com";

const errors = [];
const fail = (page, message) => errors.push(`${page}: ${message}`);

function listFiles(dir) {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) =>
    entry.isDirectory()
      ? listFiles(join(dir, entry.name))
      : [join(dir, entry.name)],
  );
}

// "dist/fr/projects/acalme/index.html" -> "/fr/projects/acalme/"
const toUrl = (file) =>
  "/" +
  relative(DIST, file)
    .split(sep)
    .join("/")
    .replace(/index\.html$/, "");

// Everything inside quotes after `name=`
const attr = (tag, name) =>
  new RegExp(`\\s${name}="([^"]*)"`, "i").exec(tag)?.[1];

const tagsOf = (html, tagName) =>
  html.match(new RegExp(`<${tagName}\\b[^>]*>`, "gi")) ?? [];

if (!existsSync(DIST)) {
  console.error("dist/ not found. Run `npm run build` first.");
  process.exit(1);
}

const files = listFiles(DIST);
const pages = new Map(
  files
    .filter((file) => file.endsWith(".html"))
    .map((file) => [toUrl(file), readFileSync(file, "utf8")]),
);

// Each page of the site, without the root redirect.
const sitePages = [...pages.keys()].filter((url) =>
  LANGS.some((lang) => url.startsWith(`/${lang}/`)),
);

// 1. Root redirects to /fr/
const root = pages.get("/");
if (!root || !/url=\/fr\/"/.test(root)) {
  fail("/", "the root page must redirect to /fr/");
}

// 1b. The 404 page exists (the server serves it for unknown URLs) and is not indexed
const notFound = pages.get("/404.html");
if (!notFound) {
  fail("/404.html", "the 404 page is missing");
} else if (!/<meta name="robots" content="noindex"/.test(notFound)) {
  fail(
    "/404.html",
    'the 404 page must contain <meta name="robots" content="noindex">',
  );
}

for (const url of sitePages) {
  const html = pages.get(url);
  const lang = url.split("/")[1];
  const rest = url.slice(lang.length + 1);

  // 2. Every page exists in both languages
  for (const other of LANGS) {
    if (!pages.has(`/${other}${rest}`)) {
      fail(url, `missing equivalent page /${other}${rest}`);
    }
  }

  // 3. <html lang> matches the URL
  const htmlLang = attr(/<html\b[^>]*>/i.exec(html)?.[0] ?? "", "lang");
  if (htmlLang !== lang) {
    fail(url, `<html lang="${htmlLang}"> but the URL is in "${lang}"`);
  }

  // 4. Canonical, hreflang, and reciprocity
  const links = tagsOf(html, "link");
  const canonical = links
    .filter((tag) => attr(tag, "rel") === "canonical")
    .map((tag) => attr(tag, "href"));
  if (canonical.length !== 1 || canonical[0] !== SITE + url) {
    fail(url, `canonical should be ${SITE + url}, found ${canonical}`);
  }
  const alternates = new Map(
    links
      .filter(
        (tag) => attr(tag, "rel") === "alternate" && attr(tag, "hreflang"),
      )
      .map((tag) => [attr(tag, "hreflang"), attr(tag, "href")]),
  );
  for (const code of [...LANGS, "x-default"]) {
    if (!alternates.has(code)) fail(url, `missing hreflang="${code}"`);
  }
  if (alternates.get("x-default") !== `${SITE}/fr${rest}`) {
    fail(url, `hreflang="x-default" should point to ${SITE}/fr${rest}`);
  }
  for (const code of LANGS) {
    const expected = `${SITE}/${code}${rest}`;
    if (alternates.get(code) !== expected) {
      fail(url, `hreflang="${code}" should be ${expected}`);
    }
    const target = pages.get(`/${code}${rest}`);
    if (!target) continue;
    // The other page must point back at this one for the same language
    const back = tagsOf(target, "link").find(
      (tag) => attr(tag, "hreflang") === lang,
    );
    if (attr(back ?? "", "href") !== `${SITE}${url}`) {
      fail(url, `/${code}${rest} does not link back with hreflang="${lang}"`);
    }
  }

  // 5. Every image has an alt attribute.
  // An empty alt is valid for a decorative image (WCAG), so it is allowed.
  for (const img of tagsOf(html, "img")) {
    if (attr(img, "alt") === undefined) {
      fail(url, `image without alt: ${attr(img, "src")}`);
    }
  }

  // 6. Internal links and assets point to something that exists
  const references = [
    ...tagsOf(html, "a").map((tag) => attr(tag, "href")),
    ...tagsOf(html, "link").map((tag) => attr(tag, "href")),
    ...tagsOf(html, "img").map((tag) => attr(tag, "src")),
    ...tagsOf(html, "script").map((tag) => attr(tag, "src")),
  ].filter((value) => value !== undefined && value !== "");

  for (const reference of new Set(references)) {
    if (/^(https?:|mailto:|tel:|data:|\/\/)/i.test(reference)) continue;
    const [path, fragment] = reference.split("#");
    const targetUrl = path === "" ? url : new URL(path, SITE + url).pathname;
    const isPage = pages.has(targetUrl);
    const asset = join(DIST, targetUrl);
    if (!isPage && !(existsSync(asset) && statSync(asset).isFile())) {
      fail(url, `broken link or asset: ${reference}`);
      continue;
    }
    if (fragment && isPage) {
      const ids = pages.get(targetUrl).matchAll(/\sid="([^"]*)"/g);
      if (![...ids].some((match) => match[1] === fragment)) {
        fail(url, `anchor not found: ${reference}`);
      }
    }
  }
}

if (errors.length > 0) {
  console.error(`\n${errors.length} problem(s) found:\n`);
  for (const message of errors) console.error(`  ✗ ${message}`);
  process.exit(1);
}
console.log(`✓ ${sitePages.length} pages checked, no problem found.`);
